
'use server';
/**
 * @fileOverview A Genkit flow for uploading a Base64 data URL to Cloudinary and saving to Firestore.
 */
import { ai } from '@/ai/genkit';
import { z } from 'genkit';
import { getFirestore as getAdminFirestore } from 'firebase-admin/firestore';
import { initializeServerApp } from '@/firebase/server-init';

const UploadMediaFromBase64InputSchema = z.object({
  fileDataUrl: z.string().describe('The file encoded as a Base64 data URL.'),
  filename: z.string().describe('The original name of the file.'),
});
export type UploadMediaFromBase64Input = z.infer<typeof UploadMediaFromBase64InputSchema>;

const UploadMediaFromBase64OutputSchema = z.object({
  success: z.boolean(),
  message: z.string(),
  url: z.string().optional(),
  mediaId: z.string().optional(),
  resource_type: z.enum(['image', 'video']).optional(),
});
export type UploadMediaFromBase64Output = z.infer<typeof UploadMediaFromBase64OutputSchema>;

/**
 * A server-side function to handle the upload of a Base64 encoded file.
 * This is a wrapper around the Genkit flow.
 * @param input The file data URL and filename.
 * @returns A promise that resolves with the result of the upload.
 */
export async function uploadMediaFromBase64(
  input: UploadMediaFromBase64Input
): Promise<UploadMediaFromBase64Output> {
  return await uploadMediaFromBase64Flow(input);
}

/**
 * A Genkit flow that uploads a Base64 data URL to Cloudinary,
 * then creates a corresponding document in Firestore.
 */
const uploadMediaFromBase64Flow = ai.defineFlow(
  {
    name: 'uploadMediaFromBase64Flow',
    inputSchema: UploadMediaFromBase64InputSchema,
    outputSchema: UploadMediaFromBase64OutputSchema,
  },
  async (input) => {
    try {
      if (
        !process.env.CLOUDINARY_CLOUD_NAME ||
        !process.env.CLOUDINARY_API_KEY ||
        !process.env.CLOUDINARY_API_SECRET
      ) {
        const errorMessage =
          'Cloudinary environment variables are not set. Please add them to your .env file.';
        console.error('Error in uploadMediaFromBase64Flow:', errorMessage);
        return {
          success: false,
          message: errorMessage,
        };
      }

      const cloudinary = (await import('cloudinary')).v2;
      cloudinary.config({
        cloud_name: process.env.CLOUDINARY_CLOUD_NAME,
        api_key: process.env.CLOUDINARY_API_KEY,
        api_secret: process.env.CLOUDINARY_API_SECRET,
        secure: true,
      });

      console.log(`Uploading file: ${input.filename}`);

      // Upload the file to Cloudinary with optimization.
      const uploadResult = await cloudinary.uploader.upload(input.fileDataUrl, {
        resource_type: 'auto',
        // Apply optimization during upload for images
        transformation: 'f_auto,q_auto'
      });

      console.log('Cloudinary upload successful:', uploadResult);

      const finalUrl = uploadResult.secure_url;
      const serverApp = await initializeServerApp();
      const firestore = getAdminFirestore(serverApp);

      const mediaData = {
        public_id: uploadResult.public_id,
        url: finalUrl,
        resource_type: uploadResult.resource_type,
        created_at: uploadResult.created_at,
        filename: input.filename,
      };

      const docRef = await firestore.collection('media').add(mediaData);

      console.log('Firestore document written with ID:', docRef.id);

      return {
        success: true,
        message: 'Media successfully uploaded and optimized.',
        url: finalUrl,
        mediaId: docRef.id,
        resource_type: uploadResult.resource_type === 'video' ? 'video' : 'image',
      };
    } catch (error: any) {
      console.error('Error in uploadMediaFromBase64Flow:', error);
      let errorMessage = 'An unexpected error occurred.';
      if (error.http_code && error.message) {
        errorMessage = `Cloudinary error: ${error.message}`;
      } else if (error.message) {
        errorMessage = error.message;
      }
      return {
        success: false,
        message: errorMessage,
      };
    }
  }
);
